import {View, Text, StyleSheet, Alert} from "react-native";
import React, {useState} from "react";
import { TextInput, Touchable, TouchableOpacity } from "react-native-web";
import { Checkbox } from 'expo-checkbox';



const LoginScreen = ({navigation}) =>{
    const [CLGID, setCLGID] = useState("");
    const [OutlookMail, setOutlookMail] = useState("");
    const [password, setPassword] = useState("");
    const [agree, setAgree] = useState(false);
    
    const submit = () =>{
      if(CLGID == "123" && OutlookMail == '123' && password == "123"){
        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
        <Alert title="Thank You!" />
        </View>
        navigation.navigate('Home');
      }else{
        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
        <Alert title="Wrong College ID or Password or Mail" />
        </View>
        
      }
      }
  return (
  <View style = {styles.mainContainer}>
    <Text 
    style={{...styles.mainHeader, fontSize: 40}}>
      WELCOME TO PlayUrCourt!
    </Text>
    <Image
     source={require('/assets/bb.png')}
   />
    <View style = {styles.inputContainer}>
      <Text style = {styles.labels}>
        Enter your College Registraion number
      </Text>
      <TextInput style = {styles.inputStyle}
      autoCaptalize = 'none'
      autoCorrect = {false}
      value = {CLGID}
      onChangeText = {(actualData) => setCLGID(actualData)}
      />
    </View>
    <View style = {styles.inputContainer}>
      <Text style = {styles.labels}>
        Enter your Outlook mail (Provided by College) 
      </Text>
      <TextInput style = {styles.inputStyle}
      autoCaptalize = 'none'
      autoCorrect = {false}
      value = {OutlookMail}
      onChangeText = {(actualData) => setOutlookMail(actualData)}/>
    </View>
    <View style = {styles.inputContainer}>
      <Text style = {styles.labels}>
        Password
      </Text>
      <TextInput style = {styles.inputStyle}
      autoCaptalize = 'none'
      autoCorrect = {false}
      secureTextEntry = {true}
      value = {password}
      onChangeText = {(actualData) => setPassword(actualData)}/>
    </View>
    <View style = {styles.wrapper}>
      <Checkbox/>
      <Text style = {styles.wrapperText}>
        GHS resident
      </Text>
      <Checkbox/>
      <Text style = {styles.wrapperText}>
        Day Scholar
      </Text>
    </View>
    <View style = {styles.wrapper}>
      <Checkbox
      value = {agree}
      onValueChange={() => setAgree(!agree)}
      color = {agree ? '#4630EB': undefined}/>
      <Text style = {styles.wrapperText}>
        I have read the Terms & Conditions
      </Text>
    </View>
    <TouchableOpacity style = {[styles.buttonStyle, {backgroundColor : agree ? '#4630EB': 'grey' }]}
      diabled = {!agree}
      onPress = {submit}>
      <Text style = {styles.buttonText}>Login</Text>
    </TouchableOpacity>
  </View>
  
  );
};

const styles = StyleSheet.create({
  mainContainer:{

    height: '100%',
    paddingHorizontal: 30,
    paddingTop: 30,
    backgroundColor: 'white'
  },
  mainHeader:{
    fontSize: 25,
    color: "#344055",
    fontWeight: 500,
    paddingTop: 20,
    paddingBottom: 15,
    textTransform: 'capitalize',
    fontFamily: 'bold'
  },
  description:{
    fontSize: 20,
    color: '#7d7d7d',
    paddingBottom: 20,
    lineHeight: 25,
    fontFamily: 'regular',


  },
  labels:{
    fontSize: 20,
    color: '#7d7d7d',
    marginTop: 10,
    marginBottom: 5,
    lineHeight: 25,
    fontFamily: 'regular',
  },
  inputContainer:{
    marginTop: 20
  },
  inputStyle:{
    borderWidth: 1,
    borderColor: 'rgba(0,0,0,3)',
    paddingHorizontal: 15,
    paddingVertical: 7,
    borderRadius: 1,
    fontFamily: 'regular',
    fontSize: 18
  },
  wrapper:{
    marginTop: 50,
    paddingLeft: 30,
  },
  wrapperText:{
    paddingLeft: 30,
    marginTop: 0,
    fontSize: 20,
  },
  buttonStyle:{
    borderRadius: 40,
    height: 50,
    justifyContent: 'center',
    alignItems: 'center',
  },
  buttonText:{
    color: '#fff',
    fontSize: 20,
    justifyContent: 'center',
    alignContent: 'center',
    fontWeight: 600
  },
  appicon:{
    marginRight: 20,
    height: 85,
    width: 85,
    marginRight: 10
  }
})
export default LoginScreen
